package erratum

import "errors"

// Use opens a resource via opener, calls Frob(input) on it, and ensures the
// resource is closed exactly once no matter what happens.
//
// While opening, TransientError values are retried; any other error is
// returned. If Frob panics with a FrobError, the resource's Defrob method is
// called with the panic's defrobTag before Close, and the error is returned.
// Any other panicked error is returned as-is (with Close still performed).
func Use(opener ResourceOpener, input string) error {
	var resource Resource
	var err error
	for {
		resource, err = opener()
		if err == nil {
			break
		}
		var transient TransientError
		if !errors.As(err, &transient) {
			return err
		}
	}

	defer func() {
		if r := recover(); r != nil {
			switch e := r.(type) {
			case FrobError:
				resource.Defrob(e.defrobTag)
				err = e
			case error:
				err = e
			default:
				panic(r)
			}
		}
		resource.Close()
	}()

	resource.Frob(input)
	return err
}

